def maxXorSubsequences(nums):
    # The set of XORs of all subsequences is the linear span of the values over GF(2).
    # Build a XOR basis, then greedily combine to get the maximum XOR value.
    basis = {}
    for x in nums:
        cur = x
        while cur:
            h = cur.bit_length() - 1
            if h in basis:
                cur ^= basis[h]
            else:
                basis[h] = cur
                break
    res = 0
    for h in sorted(basis, reverse=True):
        res = max(res, res ^ basis[h])
    return res
